import io
import logging
import os
from typing import Any, Optional

from mlflow.exceptions import MlflowException
from mlflow.protos.databricks_pb2 import INVALID_PARAMETER_VALUE

_logger = logging.getLogger(__name__)

_PROMPT_KEY = "prompt"


class _DiffusersAdapterWrapper:
    """
    PyFunc wrapper around a diffusion model adapter. Loads the base
    :py:class:`diffusers.DiffusionPipeline` lazily, applies the stored adapter weights, and
    generates images from text prompts.
    """

    def __init__(self, adapter_path: str, flavor_conf: dict, model_config: Optional[dict] = None):
        self.adapter_path = adapter_path
        self._flavor_conf = flavor_conf
        self.model_config = model_config or {}
        self._pipeline = None

    def _resolve_base_model(self) -> str:
        if self.model_config and "base_model" in self.model_config:
            return self.model_config["base_model"]
        return self._flavor_conf["base_model"]

    def _load_pipeline(self):
        import diffusers

        base_model = self._resolve_base_model()

        try:
            pipeline = diffusers.DiffusionPipeline.from_pretrained(base_model)
        except OSError as e:
            raise MlflowException(
                f"Failed to load base model '{base_model}'. Ensure the base model identifier is "
                f"correct and accessible. Error: {e}"
            )

        # Apply the adapter weights on top of the base pipeline.
        if os.path.exists(self.adapter_path) and hasattr(pipeline, "load_lora_weights"):
            weight_name = self._flavor_conf.get("weight_name")
            if weight_name:
                pipeline.load_lora_weights(self.adapter_path, weight_name=weight_name)
            else:
                pipeline.load_lora_weights(self.adapter_path)

        from mlflow.diffusers import _detect_device

        device = _detect_device()
        if device and hasattr(pipeline, "to"):
            pipeline = pipeline.to(device)

        return pipeline

    def get_raw_model(self):
        """Return the underlying diffusion pipeline, loading it on first access."""
        if self._pipeline is None:
            self._pipeline = self._load_pipeline()
        return self._pipeline

    def _extract_prompts(self, data) -> list:
        import pandas as pd

        if isinstance(data, str):
            return [data]

        if isinstance(data, list):
            return self._validate_prompt_list(data)

        if isinstance(data, dict):
            if _PROMPT_KEY not in data:
                raise MlflowException(
                    f"The input dictionary must contain a '{_PROMPT_KEY}' key.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
            value = data[_PROMPT_KEY]
            if isinstance(value, str):
                return [value]
            if isinstance(value, list):
                return self._validate_prompt_list(value)
            raise MlflowException(
                f"The '{_PROMPT_KEY}' value must be a string or list of strings.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if isinstance(data, pd.DataFrame):
            if _PROMPT_KEY in data.columns:
                column = data[_PROMPT_KEY]
            elif len(data.columns) == 1:
                column = data.iloc[:, 0]
            else:
                raise MlflowException(
                    f"The input DataFrame must contain a '{_PROMPT_KEY}' column.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
            return self._validate_prompt_list(column.tolist())

        raise MlflowException(
            f"Unsupported input type: {type(data).__name__}. Supported types are: str, "
            "list of str, dict with a 'prompt' key, and pandas DataFrame.",
            error_code=INVALID_PARAMETER_VALUE,
        )

    @staticmethod
    def _validate_prompt_list(prompts: list) -> list:
        if len(prompts) == 0:
            raise MlflowException("No prompts were provided.", error_code=INVALID_PARAMETER_VALUE)
        if any(p is None for p in prompts):
            raise MlflowException(
                "All prompt values must be strings, not None.",
                error_code=INVALID_PARAMETER_VALUE,
            )
        return list(prompts)

    @staticmethod
    def _image_to_png_bytes(image) -> bytes:
        buffer = io.BytesIO()
        image.save(buffer, format="PNG")
        return buffer.getvalue()

    def predict(self, data, params: Optional[dict[str, Any]] = None) -> list[bytes]:
        prompts = self._extract_prompts(data)
        pipeline = self.get_raw_model()

        call_kwargs = dict(params) if params else {}
        output = pipeline(prompts, **call_kwargs)

        if hasattr(output, "images"):
            images = output.images
        elif isinstance(output, dict):
            images = output.get("images")
        else:
            images = output

        if not images:
            raise MlflowException(
                "Pipeline returned no images.", error_code=INVALID_PARAMETER_VALUE
            )

        return [self._image_to_png_bytes(image) for image in images]


def _load_pyfunc(path, model_config: Optional[dict] = None):
    """Load the PyFunc implementation. Called by ``mlflow.pyfunc.load_model``.

    Args:
        path: Local filesystem path to the ``adapter_weights`` directory of the saved model.
        model_config: Optional configuration overrides applied at load time.
    """
    from mlflow.diffusers import FLAVOR_NAME
    from mlflow.utils.model_utils import _get_flavor_configuration

    model_path = os.path.dirname(path)
    flavor_conf = _get_flavor_configuration(model_path=model_path, flavor_name=FLAVOR_NAME)
    return _DiffusersAdapterWrapper(
        adapter_path=path, flavor_conf=flavor_conf, model_config=model_config
    )
